/bin/bash -lc "node --input-type=module <<'NODE'
const cases = [
  { cookie: 'member=Alice; team=Alpha', region: 'east', expected: ['Alice', 'Alpha', 'east'], absent: ['Bob', 'Beta', 'west'] },
  { cookie: 'member=Bob; team=Beta', region: 'west', expected: ['Bob', 'Beta', 'west'], absent: ['Alice', 'Alpha', 'east'] },
  { cookie: '', region: '', expected: ['Guest', 'Community', 'global'], absent: ['Alice', 'Bob'] },
]
for (const test of cases) {
  const headers = {}
  if (test.cookie) headers.cookie = test.cookie
  if (test.region) headers['x-region'] = test.region
  const response = await fetch('http://localhost:3210/', { headers })
  const body = await response.text()
  const ok = response.ok && [...test.expected, 'Workspace', '12', 'active projects'].every((value) => body.includes(value)) && test.absent.every((value) => "'!body.includes(value))
  console.log(`${test.expected.join('"' / ')}: "'${ok ? '"'PASS' : 'FAIL'} (HTTP "'${response.status})`)
  if (!ok) process.exitCode = 1
}
NODE'
